// v2.2 (22/10/2026): GET responde DIRETO do cache da leitura ciclica do 's7 in' (a cada 200 ms),
// sem entrar na fila e sem provocar leitura. Motivos: (1) a tela consulta 1x/s os dois bancos - na fila isso acumulava
// pedidos quando o PLC caia; (2) cache velho (> 2,5 s) = PLC sem leitura -> responde 503 NA HORA (a tela mostra
// "PLC sem resposta" sem esperar o watchdog de 8 s).
flow.set('chv2_html_ts', Date.now());   // v2.3: vigia 'HTML sumiu' (qualquer GET conta como HTML vivo)
const live = flow.get('chv2_live');
const ts = flow.get('chv2_live_ts') || 0;
const idade = ts ? Date.now() - ts : null;
msg.headers = { 'Content-Type': 'application/json' };
if (!live || idade === null || idade > 2500) {
  msg.statusCode = 503;
  msg.payload = { ok: false, flow: 'chaves-v2.5', erro: 'PLC sem leitura recente' + (idade === null ? ' (nenhuma leitura desde o deploy)' : ' (ha ' + Math.round(idade / 1000) + ' s)') + ' - verifique rede/PLC', idadeMs: idade };
  // log: no maximo 1 falha de GET a cada 10 s (para nao encher o log quando o PLC cai)
  const agora = Date.now();
  if (agora - (flow.get('chv2_gerr_ts') || 0) > 10000) {
    flow.set('chv2_gerr_ts', agora);
    const logs = flow.get('chv2_logs') || [];
    logs.push({ t: new Date().toISOString(), rota: 'GET', dado: '', status: 503, ok: false, ms: 0, erro: msg.payload.erro });
    if (logs.length > 1000) logs.shift();
    flow.set('chv2_logs', logs);
  }
  return msg;
}
const read = live;
const arr16 = (pref) => { const a = []; for (let i = 1; i <= 16; i++) a.push(read[pref + i] === true); return a; };
const norm = (v) => (Array.isArray(v) && Array.isArray(v[0])) ? v[0] : (Array.isArray(v) ? v : []);
const r2 = (x) => (typeof x === 'number' && isFinite(x)) ? Math.round(x * 100) / 100 : null;
// v2.5: dados por chaveamento (DB por tensao, lido por um 2o endpoint isolado)
const T = flow.get('chv2_tens'), ts2 = flow.get('chv2_tens_ts') || 0;
let porT = null;
if (T && Date.now() - ts2 <= 5000) {
  const ok = norm(T.SetupOkV), kw = norm(T.KwRealV), rm = norm(T.RmedidoV), vm = norm(T.VmedidaV);
  const dados = {};
  [220, 380, 440].forEach((v, c) => {
    const sl = (a) => a.slice(c * 16, c * 16 + 16).map(r2);
    const oks = [];
    for (let k = 0; k < 16; k++) { const pp = c * 16 + k; oks.push(((ok[pp >> 3] || 0) >> (pp & 7) & 1) === 1); }
    dados[String(v)] = { setupOk: oks, kwReal: sl(kw), rMedidoOhm: sl(rm), vMedidaV: sl(vm) };
  });
  porT = { sel: T.TensaoSel, dados };
}
msg.statusCode = 200;
msg.payload = {
  flow: 'chaves-v2.5',
  banco: '56',
  habilitada: arr16('Habilitada'),
  ligada: arr16('Ligada'),
  cbLigar: arr16('CbLigar'),
  setupOk: arr16('SetupOk'),
  kwReal: norm(read.KwReal).map(r2),
  rMedidoOhm: norm(read.RmedidoOhm).map(r2),
  rTeoricoOhm: norm(read.RteoricoOhm).map(x => (typeof x === 'number' && x > 0) ? r2(x) : null),   // v2.5: 0 = nao calculado (V_ref desconhecida)
  nominal: norm(read.Nominal).map(r2),
  chaveSel: read.ChaveSel || 0,
  usarKwReal: read.UsarKwReal === true,
  bancoLigado: read.LigarBanco === true,                    // v2.4: cbBanco.ligar
  comEt200Ok: read.ComEt200Ok === true,                     // v2.4: sbBanco.comEt200Ok (ComOk do FB101)
  seletora: read.ComEt200Ok === true ? (read.SeletoraAuto === true ? 'auto' : 'manual') : null, // v2.4: null = sem comunicacao com o ET200
  tensaoSel: porT ? porT.sel : null,                         // v2.5: 0 = nao informado, 1/2/3 = 220/380/440 V; null = DB sem leitura
  tensaoV: [220, 380, 440],
  porTensao: porT ? porT.dados : null,                       // v2.5: setup guardado por chaveamento
  wdZerou: flow.get('chv2_wd_zerou') || null,   // v2.3: {ts, qtd} do ultimo corte do vigia
  idadeMs: idade,
  lidoEm: new Date().toISOString()
};
return msg;

const b = msg.payload || {};
const falha = (t) => { msg.statusCode = 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
if (!Number.isInteger(b.indice) || b.indice < 1 || b.indice > 16) return falha('indice deve ser inteiro de 1 a 16');
if (typeof b.habilitada !== 'boolean') return falha('habilitada deve ser true/false');
msg._rota = 'HABILITAR';
return [msg, null];

const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
if (!Number.isInteger(b.indice) || b.indice < 0 || b.indice > 16) return falha('indice deve ser inteiro de 0 a 16 (0 = nenhuma)');
if (b.indice > 0) {
  const live = flow.get('chv2_live');
  if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
  if (live.LigarBanco !== true) return falha('banco BC56 desligado - acione "Ligar banco" antes de calibrar (seletora em Auto)', 409);   // v2.4
  if (live['Habilitada' + b.indice] !== true) return falha('chave ' + b.indice + ' esta desabilitada (habilite antes de selecionar)');
}
msg._rota = 'SELECIONAR';
return [msg, null];

const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
if (b.confirmado !== true) return falha('salvar requer confirmado:true');
const live = flow.get('chv2_live');
if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
if (!live.ChaveSel) return falha('nenhuma chave selecionada (POST /selecionar antes)');
const T = flow.get('chv2_tens'), ts2 = flow.get('chv2_tens_ts') || 0;   // v2.5: Setup por chaveamento
if (!T || Date.now() - ts2 > 5000) return falha('DB152 sem leitura recente - nao salvei (confira o DB152 v0.2 no PLC)', 503);
if (!(T.TensaoSel >= 1 && T.TensaoSel <= 3)) return falha('informe o chaveamento (220/380/440 V) antes de salvar o Setup', 409);
msg._rota = 'SALVAR';
msg._chaveSel = live.ChaveSel;
return [msg, null];

const b = msg.payload || {};
if (typeof b.usar !== 'boolean') { msg.statusCode = 400; msg.payload = { ok: false, erro: 'usar deve ser true/false' }; return [null, msg]; }
msg._rota = 'USARKWREAL';
return [msg, null];

if ((msg.payload || {}).confirmado !== true) {
  msg.statusCode = 400; msg.payload = { ok: false, erro: 'limpar requer confirmado:true' };
  return [null, msg];
}
const T = flow.get('chv2_tens'), ts2 = flow.get('chv2_tens_ts') || 0;
if (!T || Date.now() - ts2 > 5000) { msg.statusCode = 503; msg.payload = { ok: false, erro: 'DB152 sem leitura recente - nao limpei' }; return [null, msg]; }
if (!(T.TensaoSel >= 1 && T.TensaoSel <= 3)) { msg.statusCode = 409; msg.payload = { ok: false, erro: 'informe o chaveamento (220/380/440 V) antes de limpar: o Setup e guardado por chaveamento' }; return [null, msg]; }
msg._tensaoSel = T.TensaoSel;
msg._rota = 'LIMPAR';
return [msg, null];

const TRAVA_MAX = 10000;
const reqId = Date.now() + '_' + Math.random().toString(36).slice(2, 8);
msg._reqId = reqId;
msg.topic = reqId;
if (msg._rota !== 'ZERAR') flow.set('chv2_html_ts', Date.now());   // v2.3
const cache = flow.get('chv2_req_cache') || {};
cache[reqId] = { req: msg.req, res: msg.res };
flow.set('chv2_req_cache', cache);
const ocu = flow.get('chv2_fila_ocupado');
if (ocu) {
  if (Date.now() - ocu.ts > TRAVA_MAX) {
    node.warn('fila: liberando trava antiga reqId=' + ocu.reqId);
  } else {
    const fila = flow.get('chv2_fila_espera') || [];
    // v2.4: 'Desligar banco' e o vigia (ZERAR) furam a fila - comando de seguranca nao espera gravacoes comuns
    const prio = (msg._rota === 'BANCO' && msg.payload && msg.payload.ligar === false) || msg._rota === 'ZERAR';
    if (prio) fila.unshift(msg); else fila.push(msg);
    flow.set('chv2_fila_espera', fila);
    return null;
  }
}
flow.set('chv2_fila_ocupado', { reqId, ts: Date.now() });
return msg;

const fila = flow.get('chv2_fila_espera') || [];
const prox = fila.shift();
flow.set('chv2_fila_espera', fila);
if (prox) {
  flow.set('chv2_fila_ocupado', { reqId: prox._reqId, ts: Date.now() });
  node.send(prox);
} else {
  flow.set('chv2_fila_ocupado', null);
}
return null;

// fase 2 do SALVAR: despulsa (Salvar=false), depois de confirmado o SetupOk na fase 1
if (msg._fase === 'despulsa') {
  const ctx = flow.get('chv2_ctx');
  if (!ctx) return null;
  ctx.fase = 'despulsa';
  ctx.lerAgora = false;
  flow.set('chv2_ctx', ctx);
  const w = [{ variable: 'Salvar', payload: false }];
  return [w, { payload: null, _reqId: ctx.reqId }, null];
}

const rota = msg._rota;
let ctx = { rota, reqId: msg._reqId, fase: 'escreve', lerAgora: false };
const writes = [];
const ZERO16 = new Array(16).fill(0);
const ZERO192 = new Array(192).fill(0);
const w2 = [];   // v2.5: escritas no DB por tensao (4a saida)

if (rota === 'GET') {
  ctx.lerAgora = true;
  flow.set('chv2_ctx', ctx);
  return [null, null, { payload: '', _reqId: ctx.reqId }];
}

if (rota === 'HABILITAR') {
  const b = msg.payload;
  ctx.esp = { indice: b.indice, v: !!b.habilitada };
  if (!b.habilitada) writes.push({ variable: 'CbLigar' + b.indice, payload: false });   // v2: desabilitar derruba o comando da chave
  writes.push({ variable: 'Habilitada' + b.indice, payload: !!b.habilitada });
}
else if (rota === 'LIGAR') {
  const b = msg.payload;
  ctx.esp = { indice: b.indice, v: !!b.ligar };
  writes.push({ variable: 'CbLigar' + b.indice, payload: !!b.ligar });
}
else if (rota === 'BANCO') {   // v2.4: Ligar/Desligar banco (cbBanco.ligar)
  const b = msg.payload;
  ctx.esp = { v: !!b.ligar };
  if (!b.ligar) for (let i = 1; i <= 16; i++) writes.push({ variable: 'CbLigar' + i, payload: false }); // desligar banco abre as chaves (o FB101 tambem faz)
  writes.push({ variable: 'LigarBanco', payload: !!b.ligar });
}
else if (rota === 'SELECIONAR') {
  const b = msg.payload;
  ctx.esp = { v: b.indice };
  writes.push({ variable: 'ChaveSel', payload: b.indice });
}
else if (rota === 'SALVAR') {
  ctx.esp = { chaveSel: msg._chaveSel };
  writes.push({ variable: 'Salvar', payload: true });
}
else if (rota === 'USARKWREAL') {
  const b = msg.payload;
  ctx.esp = { v: !!b.usar };
  writes.push({ variable: 'UsarKwReal', payload: !!b.usar });
}
else if (rota === 'ZERAR') {
  // v2.3: job INTERNO do vigia (nao vem de HTTP). Derruba o comando das 16 chaves; nao mexe em Habilitada/Setup.
  ctx.esp = { zerar: true, qtd: msg._qtd || 0 };
  for (let i = 1; i <= 16; i++) writes.push({ variable: 'CbLigar' + i, payload: false });
  writes.push({ variable: 'LigarBanco', payload: false });   // v2.4: vigia tambem desliga o banco
}
else if (rota === 'LIMPAR') {
  for (let i = 1; i <= 16; i++) writes.push({ variable: 'SetupOk' + i, payload: false });
  writes.push({ variable: 'KwReal', payload: [ZERO16] });
  writes.push({ variable: 'RmedidoOhm', payload: [ZERO16] });
  writes.push({ variable: 'RteoricoOhm', payload: [ZERO16] });
  writes.push({ variable: 'SetupData', payload: [ZERO192] });
  // v2.5: o FB100 v0.3 ESPELHA o chaveamento ativo nos arrays acima a cada scan; para o LIMPAR valer, apaga-se a linha do chaveamento ATIVO no DB por tensao
  const tv = msg._tensaoSel;   // 1..3 (validado em 'valida limpar')
  ctx.esp = { tensaoSel: tv };
  w2.push({ variable: 'OkLin' + tv, payload: [[0, 0]] });
  w2.push({ variable: 'KwLin' + tv, payload: [ZERO16] });
  w2.push({ variable: 'RmLin' + tv, payload: [ZERO16] });
}
else {
  msg.statusCode = 500; msg.payload = { ok: false, erro: 'rota nao tratada: ' + rota };
  return [null, null, null];
}
flow.set('chv2_ctx', ctx);
return [writes, { payload: null, _reqId: ctx.reqId }, null, w2];

const ctx = flow.get('chv2_ctx');
if (!ctx) return null;
ctx.lerAgora = true;
flow.set('chv2_ctx', ctx);
return msg;

// Tap incondicional: toda leitura do ciclo (auto ou provocada) atualiza o cache usado pelas validacoes
// (ex.: Habilitada[indice] no /selecionar, ChaveSel no /salvar) sem precisar de outro offset novo.
flow.set('chv2_live', msg.payload);
flow.set('chv2_live_ts', Date.now());   // v2.2: idade da leitura (GET devolve 503 se > 2,5 s)
return null;

const ctx = flow.get('chv2_ctx');
if (!ctx || !ctx.lerAgora) return null;           // emissao ciclica fora de hora: ignora
const cache = flow.get('chv2_req_cache') || {};
if (!cache[ctx.reqId]) return null;                // ja respondido (ex.: timeout)
ctx.lerAgora = false;
flow.set('chv2_ctx', ctx);

const read = msg.payload || {};
const arr16 = (pref) => { const a = []; for (let i = 1; i <= 16; i++) a.push(read[pref + i] === true); return a; };
const norm = (v) => (Array.isArray(v) && Array.isArray(v[0])) ? v[0] : (Array.isArray(v) ? v : []);
const r2 = (x) => (typeof x === 'number' && isFinite(x)) ? Math.round(x * 100) / 100 : null;

const fim = (code, body) => [null, { _reqId: ctx.reqId, statusCode: code, payload: body }];

if (ctx.rota === 'GET') {
  return fim(200, {
    banco: '56',
    habilitada: arr16('Habilitada'),
    ligada: arr16('Ligada'),
    cbLigar: arr16('CbLigar'),
    setupOk: arr16('SetupOk'),
    kwReal: norm(read.KwReal).map(r2),
    rMedidoOhm: norm(read.RmedidoOhm).map(r2),
    rTeoricoOhm: norm(read.RteoricoOhm).map(r2),
    nominal: norm(read.Nominal).map(r2),
    chaveSel: read.ChaveSel || 0,
    usarKwReal: read.UsarKwReal === true,
    bancoLigado: read.LigarBanco === true,                    // v2.4: cbBanco.ligar
    comEt200Ok: read.ComEt200Ok === true,                     // v2.4: sbBanco.comEt200Ok (ComOk do FB101)
    seletora: read.ComEt200Ok === true ? (read.SeletoraAuto === true ? 'auto' : 'manual') : null, // v2.4: null = sem comunicacao com o ET200
    lidoEm: new Date().toISOString()
  });
}

if (ctx.rota === 'LIGAR') {
  const ok = read['CbLigar' + ctx.esp.indice] === ctx.esp.v;
  return ok ? fim(200, { ok: true }) : fim(500, { ok: false, erro: 'leitura de volta nao conferiu: cbLigar[' + ctx.esp.indice + ']' });
}

if (ctx.rota === 'HABILITAR') {
  const ok = read['Habilitada' + ctx.esp.indice] === ctx.esp.v;
  return ok ? fim(200, { ok: true }) : fim(500, { ok: false, erro: 'leitura de volta nao conferiu: habilitada[' + ctx.esp.indice + ']' });
}

if (ctx.rota === 'SELECIONAR') {
  const ok = read.ChaveSel === ctx.esp.v;
  return ok ? fim(200, { ok: true }) : fim(500, { ok: false, erro: 'leitura de volta nao conferiu: chaveSel' });
}

if (ctx.rota === 'SALVAR') {
  if (ctx.fase === 'despulsa') {
    const okDespulsa = read.Salvar === false;
    if (!okDespulsa) return fim(500, { ok: false, erro: 'nao consegui religar o pulso Salvar=false depois de salvar (proxima chave pode nao salvar - avise o operador)' });
    return ctx.setupOk
      ? fim(200, { ok: true })
      : fim(500, { ok: false, erro: 'PLC nao confirmou o Setup (SetupOk nao foi pra true - confira "kW sem carga"/BaseOK no FB100)' });
  }
  // fase 'escreve' (1a leitura, logo apos escrever Salvar=true): confere SetupOk e sempre despulsa em seguida
  ctx.setupOk = read['SetupOk' + ctx.esp.chaveSel] === true;
  flow.set('chv2_ctx', ctx);
  return [{ _fase: 'despulsa', _reqId: ctx.reqId, payload: null }, null];
}

if (ctx.rota === 'BANCO') {   // v2.4
  const ok = read.LigarBanco === ctx.esp.v;
  if (ok) return fim(200, { ok: true });
  return fim(500, { ok: false, erro: ctx.esp.v
    ? 'PLC nao manteve o Ligar banco (FB101 zera se a seletora nao esta em Auto ou sem comunicacao com o ET200)'
    : 'leitura de volta nao conferiu: cbBanco.ligar ainda TRUE' });
}

if (ctx.rota === 'ZERAR') {
  let resta = 0;
  for (let i = 1; i <= 16; i++) if (read['CbLigar' + i] !== false) resta++;
  if (read.LigarBanco !== false) resta++;   // v2.4: o banco tambem tem que estar desligado
  return resta ? fim(500, { ok: false, erro: 'vigia: leitura de volta mostrou ' + resta + ' cbLigar ainda TRUE apos zerar' }) : fim(200, { ok: true });
}

if (ctx.rota === 'USARKWREAL') {
  const ok = read.UsarKwReal === ctx.esp.v;
  return ok ? fim(200, { ok: true }) : fim(500, { ok: false, erro: 'leitura de volta nao conferiu: usarKwReal' });
}

if (ctx.rota === 'LIMPAR') {
  let sujo = false;
  for (let i = 1; i <= 16; i++) if (read['SetupOk' + i] !== false) sujo = true;
  return sujo ? fim(500, { ok: false, erro: 'leitura de volta apos limpar nao conferiu (setupOk)' }) : fim(200, { ok: true });
}
return fim(500, { ok: false, erro: 'rota nao tratada: ' + ctx.rota });

const reqId = msg._reqId;
const cache = flow.get('chv2_req_cache') || {};
const orig = cache[reqId];
if (!orig) return null;
// --- v2.1 log de comunicacao (so POST, e GET que falhou; o GET de 1 s da tela nao entra) ---
try {
  const _ctx = flow.get('chv2_ctx') || {};
  const _rota = _ctx.rota || '?';
  const _st = msg.statusCode || 200;
  if (_rota !== 'GET' || _st !== 200) {
    const _logs = flow.get('chv2_logs') || [];
    _logs.push({ t: new Date().toISOString(), rota: _rota, dado: _ctx.esp ? JSON.stringify(_ctx.esp) : '', status: _st, ok: _st === 200, ms: Date.now() - parseInt(String(reqId).split('_')[0], 10), erro: (msg.payload && msg.payload.erro) || '' });
    if (_logs.length > 1000) _logs.shift();
    flow.set('chv2_logs', _logs);
  }
} catch (e) { node.warn('log: ' + e.message); }
const c0 = flow.get('chv2_ctx') || {};
if (c0.rota === 'ZERAR' && (msg.statusCode || 200) === 200) flow.set('chv2_wd_zerou', { ts: new Date().toISOString(), qtd: (c0.esp && c0.esp.qtd) || 0 });
const semHttp = !orig.res;           // v2.3: job interno (ZERAR) nao tem requisicao HTTP a responder
msg.req = orig.req; msg.res = orig.res;
delete cache[reqId];
flow.set('chv2_req_cache', cache);
flow.set('chv2_ctx', null);
if (!msg.headers) msg.headers = {};
msg.headers['Content-Type'] = 'application/json';
node.send([semHttp ? null : msg, { payload: null }, { topic: reqId, reset: true }]);
return null;

const reqId = msg.topic;
const cache = flow.get('chv2_req_cache') || {};
if (!cache[reqId]) return null;
msg._reqId = reqId;
msg.statusCode = 503;
msg.payload = { ok: false, erro: 'tempo esgotado aguardando o PLC (timeout). Verifique se o PLC esta online e o DB150 existe.' };
return msg;

if (!msg._reqId) { node.warn('catch (sem requisicao): ' + (msg.error && msg.error.message)); return null; }
msg.statusCode = 500;
msg.payload = { ok: false, erro: 'erro interno: ' + (msg.error && msg.error.message ? msg.error.message : 'desconhecido') };
return msg;

const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
if (!Number.isInteger(b.indice) || b.indice < 1 || b.indice > 16) return falha('indice deve ser inteiro de 1 a 16');
if (typeof b.ligar !== 'boolean') return falha('ligar deve ser true/false');
const live = flow.get('chv2_live');
if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
if (b.ligar) {                       // desligar e sempre permitido (seguranca)
  if (live.LigarBanco !== true) return falha('banco BC56 desligado - acione "Ligar banco" antes (seletora em Auto)', 409);   // v2.4
  if (live['Habilitada' + b.indice] !== true) return falha('chave ' + b.indice + ' esta desabilitada (habilite antes de ligar)');
  if (live.ChaveSel) return falha('Setup em andamento (chave ' + live.ChaveSel + ' selecionada) - desmarque no Setup antes de ligar outras', 409);
}
msg._rota = 'LIGAR';
return [msg, null];

const limit = Math.min(parseInt((msg.req.query || {}).limit) || 100, 1000);
const logs = flow.get('chv2_logs') || [];
const ult = logs.slice(-limit).reverse();            // mais recente primeiro
const falhas = logs.filter(x => !x.ok).length;
const ms = logs.map(x => x.ms).sort((a, b) => a - b);
msg.statusCode = 200;
msg.payload = { flow: 'chaves-v2.5', banco: '56', total: logs.length, falhas: falhas,
  msMedio: ms.length ? Math.round(ms.reduce((a, b) => a + b, 0) / ms.length) : 0,
  msMax: ms.length ? ms[ms.length - 1] : 0, lidoEm: new Date().toISOString(), logs: ult };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// v2.3 (22/10/2026) - VIGIA "HTML SUMIU" (BC56, DB150)
// Motivo: o comando cbLigar fica TRUE no PLC mesmo depois de fechar o navegador. Se o HTML nao consulta este flow
// por WD_HTML_S segundos (padrao 30; muda em: aba > Propriedades > Variaveis de ambiente), zera CbLigar1..16 pela
// mesma fila das escritas (job interno 'ZERAR': escreve, espera 450 ms, le de volta e confere).
// So age se: (1) ha leitura recente do PLC (<= 2,5 s) - sem PLC nao ha como escrever; (2) existe algum cbLigar TRUE;
// (3) a fila esta livre; (4) passaram 5 s da ultima tentativa (se falhar, tenta de novo).
// Nao mexe em Habilitada, Setup, kW real, Salvar nem ChaveSel.
const AGORA = Date.now();
const LIM_S = Number(env.get('WD_HTML_S')) || 30;
const live = flow.get('chv2_live');
const ts = flow.get('chv2_live_ts') || 0;
if (!live || AGORA - ts > 2500) return null;
let t0 = flow.get('chv2_start_ts');
if (!t0) { t0 = AGORA; flow.set('chv2_start_ts', t0); }       // apos Deploy/reinicio, conta a partir daqui
const ref = Math.max(flow.get('chv2_html_ts') || 0, t0);
if (AGORA - ref < LIM_S * 1000) return null;
let qtd = 0;
for (let i = 1; i <= 16; i++) if (live['CbLigar' + i] === true) qtd++;
const bancoLig = live.LigarBanco === true;   // v2.4: banco ligado sem HTML tambem conta
if (!qtd && !bancoLig) return null;
if (flow.get('chv2_fila_ocupado')) return null;
if (AGORA - (flow.get('chv2_wd_last') || 0) < 5000) return null;
flow.set('chv2_wd_last', AGORA);
node.warn('vigia HTML sumiu: ' + qtd + ' cbLigar TRUE' + (bancoLig ? ' + banco ligado' : '') + ' sem HTML ha > ' + LIM_S + ' s - zerando (DB150)');
return { _rota: 'ZERAR', _qtd: qtd, payload: null };

// v2.4 (24/10/2026): Ligar/Desligar banco -> cbBanco.ligar. Desligar e SEMPRE permitido (seguranca).
// Ligar exige comunicacao 1515-ET200 viva e seletora em Auto (o FB101 v0.4 aplica a mesma regra no PLC).
const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
if (typeof b.ligar !== 'boolean') return falha('ligar deve ser true/false');
if (b.ligar) {
  const live = flow.get('chv2_live');
  if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
  if (live.ComEt200Ok !== true) return falha('sem comunicacao 1515-ET200 (FB101 ComOk = FALSE) - banco nao pode ligar', 409);
  if (live.SeletoraAuto !== true) return falha('seletora do banco BC56 em Manual (local) - gire para Auto (remoto)', 409);
}
msg._rota = 'BANCO';
return [msg, null];

flow.set('chv2_tens', msg.payload);
flow.set('chv2_tens_ts', Date.now());
return null;

// v2.5: informa ao PLC o chaveamento do banco (220/380/440 V). Escreve DB152 (TensaoSel = 1..3) e confere a releitura.
const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, null, msg]; };
const mapa = { 0: 0, 220: 1, 380: 2, 440: 3 };   // v2.6: 0 = desliga o chaveamento (TensaoSel = 0 = nao informado)
const idx = mapa[Number(b.tensao)];
if (idx === undefined) return falha('tensao deve ser 0 (nao informado), 220, 380 ou 440');
const live = flow.get('chv2_live');
if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
if (live.ChaveSel) return falha('ha uma chave selecionada no Setup - desmarque-a antes de mudar o chaveamento', 409);
const ts2 = flow.get('chv2_tens_ts') || 0;
if (!ts2 || Date.now() - ts2 > 5000) return falha('DB152 sem leitura recente - confira se o DB existe no PLC (v0.2) e a rede', 503);
flow.set('chv2_html_ts', Date.now());
msg._idx = idx; msg._tensao = Number(b.tensao); msg._t0 = Date.now();
return [[{ variable: 'TensaoSel', payload: idx }], msg, null];

const t = flow.get('chv2_tens') || {};
const ok = t.TensaoSel === msg._idx;
msg.statusCode = ok ? 200 : 500;
msg.payload = ok ? { ok: true, tensao: msg._tensao, tensaoSel: msg._idx } : { ok: false, erro: 'leitura de volta nao conferiu: tensaoSel (lido ' + t.TensaoSel + ', esperado ' + msg._idx + ')' };
msg.headers = { 'Content-Type': 'application/json' };
try {
  const logs = flow.get('chv2_logs') || [];
  logs.push({ t: new Date().toISOString(), rota: 'TENSAO', dado: JSON.stringify({ tensao: msg._tensao }), status: msg.statusCode, ok: ok, ms: Date.now() - (msg._t0 || Date.now()), erro: ok ? '' : msg.payload.erro });
  if (logs.length > 1000) logs.shift();
  flow.set('chv2_logs', logs);
} catch (e) { node.warn('log: ' + e.message); }
return msg;
